"""Builds the files of the tv-morphe-patches repository in .github/tv-repo.

The TV repository's issue forms, security policy, notice, and license come from
this repository's copies, so they stay in step. The issue forms list only the
Android TV apps and drop the phone-or-TV question. The README in
.github/tv-repo is written by hand and left alone.

publish_tv_bundle.py copies .github/tv-repo to the TV repository's main branch.

    python3 .github/scripts/build_tv_repo.py          # write the files
    python3 .github/scripts/build_tv_repo.py --check  # fail if they are out of date (CI)
"""

import argparse
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / ".github" / "tv-repo"
PATCHES = ROOT / "patches/src/main/kotlin/semicoloncolonel/mobilestream/patches"
MOBILE = "https://github.com/semicoloncolonel/mobile-morphe-patches"
TV = "https://github.com/semicoloncolonel/tv-morphe-patches"
HEADER = "# Generated by mobile-morphe-patches/.github/scripts/build_tv_repo.py. Edit the source there.\n"
FORMS = ["0-version-or-build.yml", "1-bug-report.yml", "2-enhancement.yml",
         "3-new-app-or-patch.yml", "4-something-else.yml"]

# Text that only fits the phone repository, and its TV replacement.
REPLACEMENTS = [
    (f"{MOBILE}/issues", f"{TV}/issues"),
    (f"{MOBILE}/security", f"{TV}/security"),
    (f"{MOBILE}/blob/main/SECURITY.md", f"{TV}/blob/main/SECURITY.md"),
    (f"{MOBILE}#readme", f"{TV}#readme"),
    ("The maker and model of the phone, tablet, or TV device.",
     "The maker and model of the TV device, such as an NVIDIA Shield TV or a Chromecast with Google TV."),
    ("On a phone, see Settings > About phone. On a TV, see Settings > System > About.",
     "See Settings > System > About."),
]


def tv_bundle_apps() -> list[str]:
    text = (ROOT / "patches/build.gradle.kts").read_text()
    match = re.search(r"val tvBundleApps = setOf\((.*?)\)", text, re.S)
    return re.findall(r'"([^"]+)"', match.group(1))


def tv_app_names() -> set[str]:
    """The names the forms use for the TV apps, from each app's Constants.

    An app with a separate Android TV entry, such as "Apple TV (Android TV)",
    is listed by that entry's name only.
    """
    names = set()
    for app in tv_bundle_apps():
        found = set(re.findall(r'name = "([^"]+)"', (PATCHES / app / "shared/Constants.kt").read_text()))
        tv = {name for name in found if name.endswith("(Android TV)")}
        names |= tv or found
    return names


def replace_all(text: str) -> str:
    for old, new in REPLACEMENTS:
        text = text.replace(old, new)
    return text


def tv_form(text: str, names: set[str]) -> str:
    """Keeps the TV apps in the App dropdown and drops the phone-or-TV question."""
    parts = re.split(r"(?m)^(?=  - type:)", text)
    head, items = parts[0], parts[1:]
    kept = []
    for item in items:
        if re.search(r"(?m)^    id: build$", item):
            continue
        if re.search(r"(?m)^    id: app$", item):
            item = "".join(
                line for line in item.splitlines(keepends=True)
                if not (m := re.match(r'\s+- "([^"]+)"$', line))
                or m.group(1).startswith("Other") or m.group(1) in names
            )
        kept.append(item)
    return replace_all(head + "".join(kept))


def outputs() -> dict[Path, str]:
    names = tv_app_names()
    files = {}
    for form in FORMS:
        source = (ROOT / ".github/ISSUE_TEMPLATE" / form).read_text()
        files[OUT / ".github/ISSUE_TEMPLATE" / form] = HEADER + tv_form(source, names)
    config = (ROOT / ".github/ISSUE_TEMPLATE/config.yml").read_text()
    config = config.replace("contact_links:\n", (
        "contact_links:\n"
        "  - name: 📺 Android TV\n"
        f"    url: {MOBILE}/blob/main/docs/android-tv.md\n"
        "    about: The Android TV apps, and how to get the Android TV build of each.\n"
    ), 1)
    files[OUT / ".github/ISSUE_TEMPLATE/config.yml"] = HEADER + replace_all(config)
    files[OUT / "SECURITY.md"] = replace_all((ROOT / "SECURITY.md").read_text())
    files[OUT / "NOTICE"] = (ROOT / "NOTICE").read_text()
    files[OUT / "LICENSE"] = (ROOT / "LICENSE").read_text()
    return files


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    stale = []
    for path, text in outputs().items():
        if path.exists() and path.read_text() == text:
            continue
        stale.append(path.relative_to(ROOT))
        if not args.check:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text)
    if args.check and stale:
        print("Out of date; run python3 .github/scripts/build_tv_repo.py:")
        print("\n".join(f"  {p}" for p in stale))
        return 1
    print("\n".join(f"wrote {p}" for p in stale) or "up to date")
    return 0


if __name__ == "__main__":
    sys.exit(main())
